-- ScholarTasks starter practice questions (core subjects, grades 8-12), written for ScholarTasks.
-- Safe to run twice: questions already in the bank are skipped. All start as WAITING for teacher review at /admin/questions.
insert into practice_questions (subject, topic, kind, question, options, answer_index, model_answer, explanation, status)
select v.subject, v.topic, v.kind, v.question, v.options, v.answer_index, v.model_answer, v.explanation, 'pending' from (values
  ($q$Algebra I$q$, $q$Linear equations$q$, 'mc', $q$Solve 3x + 7 = 22.$q$, $q$["x = 3", "x = 5", "x = 7", "x = 29/3"]$q$::jsonb, 1, null, $q$Subtract 7 from both sides to get 3x = 15, then divide by 3: x = 5.$q$),
  ($q$Algebra I$q$, $q$Slope$q$, 'mc', $q$What is the slope of the line through (2, 3) and (6, 11)?$q$, $q$["2", "4", "1/2", "8"]$q$::jsonb, 0, null, $q$Slope = change in y / change in x = (11 - 3) / (6 - 2) = 8 / 4 = 2.$q$),
  ($q$Algebra I$q$, $q$Expressions$q$, 'mc', $q$Simplify 2(x + 4) - 3x.$q$, $q$["-x + 8", "5x + 8", "-x + 4", "x + 8"]$q$::jsonb, 0, null, $q$Distribute: 2x + 8 - 3x. Combine like terms: -x + 8.$q$),
  ($q$Algebra I$q$, $q$Quadratics$q$, 'mc', $q$Which values of x solve x² = 49?$q$, $q$["7 only", "-7 and 7", "49", "24.5"]$q$::jsonb, 1, null, $q$Both 7 × 7 and (-7) × (-7) equal 49, so there are two solutions.$q$),
  ($q$Algebra I$q$, $q$Functions$q$, 'mc', $q$If f(x) = 2x² - 1, what is f(3)?$q$, $q$["17", "35", "11", "5"]$q$::jsonb, 0, null, $q$f(3) = 2(3²) - 1 = 2(9) - 1 = 17. Square first, then multiply.$q$),
  ($q$Algebra I$q$, $q$Slope-intercept form$q$, 'mc', $q$What is the y-intercept of y = -4x + 9?$q$, $q$["9", "-4", "4", "-9"]$q$::jsonb, 0, null, $q$In y = mx + b, b is the y-intercept. Here b = 9, so the line crosses the y-axis at (0, 9).$q$),
  ($q$Algebra I$q$, $q$Systems of equations$q$, 'written', $q$Solve the system y = 2x + 1 and y = -x + 7. Explain your steps.$q$, null, null, $q$Set the right sides equal: 2x + 1 = -x + 7, so 3x = 6 and x = 2. Substitute: y = 2(2) + 1 = 5. The solution is (2, 5). Check in the second equation: -2 + 7 = 5.$q$, null),
  ($q$Geometry$q$, $q$Triangles$q$, 'mc', $q$Two angles of a triangle are 50° and 60°. What is the third angle?$q$, $q$["70°", "80°", "90°", "110°"]$q$::jsonb, 0, null, $q$The angles of a triangle add to 180°: 180 - 50 - 60 = 70°.$q$),
  ($q$Geometry$q$, $q$Pythagorean theorem$q$, 'mc', $q$A right triangle has legs of 6 and 8. How long is the hypotenuse?$q$, $q$["10", "14", "48", "12"]$q$::jsonb, 0, null, $q$a² + b² = c²: 36 + 64 = 100, and √100 = 10.$q$),
  ($q$Geometry$q$, $q$Circles$q$, 'mc', $q$What is the area of a circle with radius 3?$q$, $q$["9π", "6π", "3π", "18π"]$q$::jsonb, 0, null, $q$Area = πr² = π × 3² = 9π. (6π is the circumference.)$q$),
  ($q$Geometry$q$, $q$Polygons$q$, 'mc', $q$What is the sum of the interior angles of a hexagon?$q$, $q$["720°", "540°", "360°", "1080°"]$q$::jsonb, 0, null, $q$Sum = (n - 2) × 180° = (6 - 2) × 180° = 720°.$q$),
  ($q$Geometry$q$, $q$Angle relationships$q$, 'mc', $q$Two angles are supplementary. One is 115°. What is the other?$q$, $q$["65°", "75°", "25°", "245°"]$q$::jsonb, 0, null, $q$Supplementary angles add to 180°: 180 - 115 = 65°.$q$),
  ($q$Geometry$q$, $q$Volume$q$, 'mc', $q$What is the volume of a rectangular box that is 2 by 3 by 5 units?$q$, $q$["30 cubic units", "10 cubic units", "31 cubic units", "60 cubic units"]$q$::jsonb, 0, null, $q$Volume = length × width × height = 2 × 3 × 5 = 30.$q$),
  ($q$Geometry$q$, $q$Triangles$q$, 'written', $q$Explain why the two acute angles in a right triangle must add up to 90°.$q$, null, null, $q$The three angles of any triangle add to 180°. A right triangle has one 90° angle, so the other two angles must share the remaining 180 - 90 = 90°.$q$, null),
  ($q$Biology$q$, $q$Cells$q$, 'mc', $q$Which organelle makes most of a cell's usable energy (ATP)?$q$, $q$["Mitochondria", "Ribosome", "Nucleus", "Golgi apparatus"]$q$::jsonb, 0, null, $q$Mitochondria carry out cellular respiration, which releases energy stored in glucose as ATP.$q$),
  ($q$Biology$q$, $q$Photosynthesis$q$, 'mc', $q$What does photosynthesis produce?$q$, $q$["Glucose and oxygen", "Carbon dioxide and water", "Only oxygen", "Proteins"]$q$::jsonb, 0, null, $q$Plants use light, carbon dioxide and water to make glucose, releasing oxygen.$q$),
  ($q$Biology$q$, $q$DNA$q$, 'mc', $q$In DNA, which base pairs with adenine (A)?$q$, $q$["Thymine (T)", "Guanine (G)", "Cytosine (C)", "Uracil (U)"]$q$::jsonb, 0, null, $q$In DNA, A pairs with T and C pairs with G. Uracil replaces thymine only in RNA.$q$),
  ($q$Biology$q$, $q$Genetics$q$, 'mc', $q$Two parents are both Bb. What fraction of offspring are expected to be bb?$q$, $q$["1/4", "1/2", "3/4", "0"]$q$::jsonb, 0, null, $q$A Punnett square gives BB, Bb, Bb, bb, so 1 out of 4 is bb.$q$),
  ($q$Biology$q$, $q$Evolution$q$, 'mc', $q$Which statement best describes natural selection?$q$, $q$["Individuals with helpful traits survive and reproduce more, passing those traits on", "Individuals change their own genes during life to adapt", "All individuals in a population are identical", "Traits gained during life, like big muscles, are inherited"]$q$::jsonb, 0, null, $q$Natural selection works on inherited variation: helpful inherited traits become more common over generations.$q$),
  ($q$Biology$q$, $q$Cell division$q$, 'mc', $q$Which type of cell division makes sex cells (gametes)?$q$, $q$["Meiosis", "Mitosis", "Binary fission", "Osmosis"]$q$::jsonb, 0, null, $q$Meiosis makes four genetically different cells with half the chromosomes. Mitosis makes identical body cells.$q$),
  ($q$Biology$q$, $q$Cell division$q$, 'written', $q$Explain two differences between mitosis and meiosis.$q$, null, null, $q$Mitosis makes 2 genetically identical cells with the full set of chromosomes, for growth and repair. Meiosis has two divisions and makes 4 genetically different cells with half the chromosomes (gametes) for sexual reproduction.$q$, null),
  ($q$Physical Science and Chemistry$q$, $q$Atoms$q$, 'mc', $q$What does an element's atomic number tell you?$q$, $q$["The number of protons", "The number of neutrons", "Protons plus neutrons", "The number of electron shells"]$q$::jsonb, 0, null, $q$The atomic number is the number of protons, which defines the element.$q$),
  ($q$Physical Science and Chemistry$q$, $q$Acids and bases$q$, 'mc', $q$A solution has a pH of 3. It is:$q$, $q$["Acidic", "Basic", "Neutral", "A pure metal"]$q$::jsonb, 0, null, $q$pH below 7 is acidic, 7 is neutral, and above 7 is basic.$q$),
  ($q$Physical Science and Chemistry$q$, $q$Chemical equations$q$, 'mc', $q$Complete the balanced equation: 2H₂ + O₂ → ?$q$, $q$["2H₂O", "H₂O", "H₂O₂", "2H₂O₂"]$q$::jsonb, 0, null, $q$4 hydrogen atoms and 2 oxygen atoms on the left make 2 water molecules on the right.$q$),
  ($q$Physical Science and Chemistry$q$, $q$Motion$q$, 'mc', $q$An object travels 20 meters in 4 seconds. What is its average speed?$q$, $q$["5 m/s", "80 m/s", "24 m/s", "16 m/s"]$q$::jsonb, 0, null, $q$Speed = distance / time = 20 m / 4 s = 5 m/s.$q$),
  ($q$Physical Science and Chemistry$q$, $q$Forces$q$, 'mc', $q$Which equation is Newton's second law?$q$, $q$["F = ma", "Every action has an equal and opposite reaction", "An object at rest stays at rest unless acted on", "E = mc²"]$q$::jsonb, 0, null, $q$Newton's second law: net force equals mass times acceleration.$q$),
  ($q$Physical Science and Chemistry$q$, $q$Matter$q$, 'mc', $q$Which of these is a chemical change?$q$, $q$["Iron rusting", "Ice melting", "Sugar dissolving in water", "Glass breaking"]$q$::jsonb, 0, null, $q$Rusting makes a new substance (iron oxide). The others change form but not the substance.$q$),
  ($q$Physical Science and Chemistry$q$, $q$Forces$q$, 'written', $q$A 2 kg cart speeds up at 3 m/s². What net force acts on it? Show your work.$q$, null, null, $q$F = ma = 2 kg × 3 m/s² = 6 N (newtons).$q$, null),
  ($q$U.S. History$q$, $q$Founding$q$, 'mc', $q$Which document announced the colonies' independence in 1776?$q$, $q$["The Declaration of Independence", "The Constitution", "The Bill of Rights", "The Articles of Confederation"]$q$::jsonb, 0, null, $q$The Declaration of Independence was adopted on July 4, 1776. The Constitution came in 1787.$q$),
  ($q$U.S. History$q$, $q$Reconstruction$q$, 'mc', $q$What did the 13th Amendment do?$q$, $q$["Abolished slavery", "Gave women the right to vote", "Banned alcohol", "Created the income tax"]$q$::jsonb, 0, null, $q$The 13th Amendment (1865) abolished slavery. Women's suffrage was the 19th.$q$),
  ($q$U.S. History$q$, $q$Great Depression$q$, 'mc', $q$The New Deal was a response to:$q$, $q$["The Great Depression", "World War I", "The Civil War", "The Cold War"]$q$::jsonb, 0, null, $q$Franklin Roosevelt's New Deal programs in the 1930s aimed to bring relief and recovery from the Depression.$q$),
  ($q$U.S. History$q$, $q$Civil rights$q$, 'mc', $q$What did Brown v. Board of Education (1954) decide?$q$, $q$["Racial segregation in public schools is unconstitutional", "Courts can strike down laws (judicial review)", "\"Separate but equal\" is allowed", "Women have the right to vote"]$q$::jsonb, 0, null, $q$Brown overturned "separate but equal" in public schools. Judicial review came from Marbury v. Madison.$q$),
  ($q$U.S. History$q$, $q$Expansion$q$, 'mc', $q$Which 1803 purchase roughly doubled the size of the United States?$q$, $q$["The Louisiana Purchase", "The Alaska Purchase", "The Gadsden Purchase", "The purchase of Florida"]$q$::jsonb, 0, null, $q$The U.S. bought the Louisiana Territory from France in 1803.$q$),
  ($q$U.S. History$q$, $q$Cold War$q$, 'mc', $q$Who were the main rivals in the Cold War?$q$, $q$["The United States and the Soviet Union", "The United States and Germany", "Britain and France", "The United States and Japan"]$q$::jsonb, 0, null, $q$The Cold War (about 1947-1991) was a rivalry between the U.S. and the Soviet Union.$q$),
  ($q$U.S. History$q$, $q$Civil War$q$, 'written', $q$Describe two causes of the American Civil War.$q$, null, null, $q$Disagreement over slavery and whether it could spread to new western territories; conflict over states' rights versus federal power; economic differences between North and South; and Lincoln's election in 1860, which led Southern states to secede. Two of these, explained, is a full answer.$q$, null),
  ($q$American Government$q$, $q$Constitution$q$, 'mc', $q$What are the three branches of the U.S. government?$q$, $q$["Legislative, executive and judicial", "House, Senate and President", "Federal, state and local", "Army, Navy and Air Force"]$q$::jsonb, 0, null, $q$Congress makes laws, the President carries them out, and the courts interpret them.$q$),
  ($q$American Government$q$, $q$Congress$q$, 'mc', $q$How many U.S. senators does each state have?$q$, $q$["2", "1", "It depends on population", "4"]$q$::jsonb, 0, null, $q$Every state has 2 senators. Seats in the House depend on population.$q$),
  ($q$American Government$q$, $q$Rights$q$, 'mc', $q$What are the first ten amendments to the Constitution called?$q$, $q$["The Bill of Rights", "The Federalist Papers", "The Preamble", "The Articles of Confederation"]$q$::jsonb, 0, null, $q$The Bill of Rights (1791) lists basic rights such as speech, religion and a fair trial.$q$),
  ($q$American Government$q$, $q$Lawmaking$q$, 'mc', $q$Who can veto a bill passed by Congress?$q$, $q$["The President", "The Supreme Court", "The Speaker of the House", "State governors"]$q$::jsonb, 0, null, $q$The President can veto a bill; Congress can override with a two-thirds vote in both chambers.$q$),
  ($q$American Government$q$, $q$Checks and balances$q$, 'mc', $q$What does "checks and balances" mean?$q$, $q$["Each branch can limit the powers of the others", "States approve the federal budget", "Citizens vote on every law", "The President controls the courts"]$q$::jsonb, 0, null, $q$Examples: the President's veto, Senate approval of judges, and courts ruling laws unconstitutional.$q$),
  ($q$American Government$q$, $q$Rights$q$, 'mc', $q$Freedom of speech is protected by which amendment?$q$, $q$["The First", "The Second", "The Fifth", "The Tenth"]$q$::jsonb, 0, null, $q$The First Amendment protects speech, religion, press, assembly and petition.$q$),
  ($q$American Government$q$, $q$Lawmaking$q$, 'written', $q$Explain how a bill becomes a federal law.$q$, null, null, $q$A member of Congress introduces the bill (tax bills start in the House). A committee studies it, then the House and Senate each vote. Both must pass the same version. The President signs it into law or vetoes it; Congress can override a veto with a two-thirds vote in both chambers.$q$, null),
  ($q$English Language Arts$q$, $q$Sentences$q$, 'mc', $q$Which is a complete sentence?$q$, $q$["Because the bus was late.", "Running down the hall.", "The bus was late, so we missed first period.", "After the game ended."]$q$::jsonb, 2, null, $q$A complete sentence has a subject and verb and expresses a full thought. The others are fragments.$q$),
  ($q$English Language Arts$q$, $q$Literature$q$, 'mc', $q$The theme of a story is:$q$, $q$["Its central message or insight about life", "The time and place it happens", "The main character", "The order of events"]$q$::jsonb, 0, null, $q$Setting is time and place; plot is the order of events; theme is the message.$q$),
  ($q$English Language Arts$q$, $q$Figurative language$q$, 'mc', $q$"The wind whispered through the trees" is an example of:$q$, $q$["Personification", "Simile", "Hyperbole", "Alliteration"]$q$::jsonb, 0, null, $q$Giving a human action (whispering) to something non-human is personification.$q$),
  ($q$English Language Arts$q$, $q$Usage$q$, 'mc', $q$Which sentence is correct?$q$, $q$["Their going to the game later.", "They're going to the game later.", "There going to the game later.", "Theyre going to the game later."]$q$::jsonb, 1, null, $q$They're = they are. Their shows ownership; there is a place.$q$),
  ($q$English Language Arts$q$, $q$Writing$q$, 'mc', $q$A thesis statement is:$q$, $q$["The main argument of an essay", "A quote from a source", "The last paragraph", "A list of sources"]$q$::jsonb, 0, null, $q$The thesis states the main claim the essay will support, usually near the end of the introduction.$q$),
  ($q$English Language Arts$q$, $q$Figurative language$q$, 'mc', $q$"Her backpack weighed a ton" is an example of:$q$, $q$["Hyperbole", "Simile", "Personification", "Onomatopoeia"]$q$::jsonb, 0, null, $q$Hyperbole is deliberate exaggeration for effect.$q$),
  ($q$English Language Arts$q$, $q$Sentences$q$, 'written', $q$Fix this run-on sentence: "I finished my homework I went to practice."$q$, null, null, $q$Any correct fix works, for example: "I finished my homework, and then I went to practice." or "I finished my homework. Then I went to practice." or "I finished my homework; I went to practice."$q$, null),
  ($q$Economics$q$, $q$Scarcity$q$, 'mc', $q$What is opportunity cost?$q$, $q$["The value of the next best choice you give up", "The price you pay in money", "The total cost of everything you buy", "The cost of making a product"]$q$::jsonb, 0, null, $q$Every choice has a trade-off; the opportunity cost is the best alternative you didn't choose.$q$),
  ($q$Economics$q$, $q$Supply and demand$q$, 'mc', $q$If demand for a product rises and supply stays the same, the price usually:$q$, $q$["Rises", "Falls", "Stays the same", "Drops to zero"]$q$::jsonb, 0, null, $q$More buyers competing for the same supply pushes the price up.$q$),
  ($q$Economics$q$, $q$Macroeconomics$q$, 'mc', $q$Inflation is:$q$, $q$["A general rise in prices over time", "A fall in unemployment", "An increase in taxes", "Growth in the economy's output"]$q$::jsonb, 0, null, $q$Inflation means money buys less than before because prices overall have gone up.$q$),
  ($q$Economics$q$, $q$Money and banking$q$, 'mc', $q$What is the central bank of the United States?$q$, $q$["The Federal Reserve", "The U.S. Treasury", "Congress", "The IRS"]$q$::jsonb, 0, null, $q$The Federal Reserve sets monetary policy, including key interest rates.$q$),
  ($q$Economics$q$, $q$Macroeconomics$q$, 'mc', $q$What does GDP measure?$q$, $q$["The total value of final goods and services produced in a country in a period", "The government's debt", "The money in people's bank accounts", "Exports minus imports"]$q$::jsonb, 0, null, $q$Gross domestic product is the market value of everything a country produces in a year (or quarter).$q$),
  ($q$Economics$q$, $q$Personal finance$q$, 'mc', $q$When a budget's spending is greater than its income, it has a:$q$, $q$["Deficit", "Surplus", "Balance", "Dividend"]$q$::jsonb, 0, null, $q$A deficit is spending more than you take in; a surplus is the opposite.$q$),
  ($q$Economics$q$, $q$Scarcity$q$, 'written', $q$Explain opportunity cost using an example from your own week.$q$, null, null, $q$Opportunity cost is the next best thing you give up when you choose. A good answer names a real choice and what was given up, for example: "I worked a shift on Saturday, so my opportunity cost was the study time for my chemistry test."$q$, null)
) as v(subject, topic, kind, question, options, answer_index, model_answer, explanation)
where not exists (select 1 from practice_questions p where p.subject = v.subject and p.question = v.question);
